use vstd::prelude::*;

verus! {
    spec fn fibonacci(n: nat) -> vec<i32>
        requires
            n <= 0x1_0000_0000, // Ensure n is within a reasonable range to avoid overflow
        ensures
            |result| result.len() == n as usize && 
                      (forall |i: nat| i < n ==> result[i] == fib(i)),
    {
        // Fibonacci sequence generation logic
        let mut fib_sequence = Vec::with_capacity(n);
        
        // Initialize the first two Fibonacci numbers
        fib_sequence.push(0); // F(0)
        fib_sequence.push(1); // F(1)

        // Calculate Fibonacci numbers from F(2) to F(n-1)
        for i in 2..n
            invariant
                fib_sequence.len() == i as usize + 1,
                (forall |j: nat| j < i ==> fib_sequence[j] == fib(j)),
                fib_sequence.len() <= n as usize,
            decreases n - i,
        {
            let next_fib = fib_sequence[i - 1] + fib_sequence[i - 2];
            fib_sequence.push(next_fib);
        }

        fib_sequence
    }

    // Specification for Fibonacci numbers
    spec fn fib(n: nat) -> nat
        decreases n,
    {
        if n == 0 {
            0
        } else if n == 1 {
            1
        } else {
            fib((n - 2) as nat) + fib((n - 1) as nat)
        }
    }
}

